#include <stdint.h>

#define RCC_APB2ENR  (*(volatile uint32_t*)0x40021018)
#define GPIOC_CRH    (*(volatile uint32_t*)0x40011004)
#define GPIOC_BSRR   (*(volatile uint32_t*)0x40011010)   /* cơ sở + 0x10 */
#define GPIOC_BRR    (*(volatile uint32_t*)0x40011014)   /* cơ sở + 0x14 */
#define RCC_CR      (*(volatile uint32_t*)0x40021000)
#define RCC_CFGR    (*(volatile uint32_t*)0x40021004)
#define FLASH_ACR   (*(volatile uint32_t*)0x40022000)
#define SET_BIT( reg, n) ((reg) |= (1U << (n)))

static void delay(volatile uint32_t n)
{
    while (n--) { }
}

int main(void)
{
	/* Bật clock GPIOC và cấu hình PC13 */
	SET_BIT(RCC_APB2ENR, 4);
	GPIOC_CRH &= ~(0xFU << 20);
	GPIOC_CRH |=  (0x2U << 20);

	/* Bật HSE và đợi ổn định */
	SET_BIT(RCC_CR, 16);
	while (!(RCC_CR & (1U << 17))) { }

	/* Flash: 2 wait states và prefetch */
	FLASH_ACR &= ~(0x7U << 0);
	FLASH_ACR |=  (0x2U << 0);
	SET_BIT(FLASH_ACR, 4);

	/* Cấu hình PLL (HSE x9) và APB1 chia 2 */
	SET_BIT(RCC_CFGR, 16);
	RCC_CFGR &= ~(0xFU << 18);  RCC_CFGR |= (0x7U << 18);
	RCC_CFGR &= ~(0x7U << 8);   RCC_CFGR |= (0x4U << 8);

	/* Bật PLL và đợi khóa tần số */
	SET_BIT(RCC_CR, 24);
	while (!(RCC_CR & (1U << 25))) { }

	/* Chuyển SYSCLK sang PLL và đợi xác nhận */
	RCC_CFGR &= ~(0x3U << 0);
	RCC_CFGR |=  (0x2U << 0);
	while (((RCC_CFGR >> 2) & 0x3U) != 0x2U) {
		for (;;)
		{
			GPIOC_BSRR = (1U << 29);   /* LED sáng */
			delay(1000000);
			GPIOC_BSRR = (1U << 13);   /* LED tắt */
			delay(1000000);
		}
    }
}
